bool Vop3p::has_encoded_dpp() const {
  return supports_dpp_opcode() && inst_.src0 == amdgpu::SRC_DPP;
}

bool Vop3p::has_encoded_dpp8() const {
  return supports_dpp_opcode() && amdgpu::dpp::is_src_dpp8(inst_.src0);
}

